-- Canonical guarded history copy of applied 0029_reports_legacy_boundaries_and_timeline.sql.
-- Already-present changes are deliberately not re-applied.
DO $reports_history$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.admin_sign_in_people(date,date,text,timestamptz)') AND prosrc LIKE '%reports_people_rows%') THEN
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.reports_access_guard()'::regprocedure); d:=replace(d,'IF auth.uid() IS NOT NULL AND NOT public.reports_can','IF auth.uid() IS NOT NULL AND (TG_OP<>''INSERT'' OR NEW.role<>''viewer'') AND NOT public.reports_can'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.admin_sign_in_people(_from date,_to date,_accounts text DEFAULT 'real',_as_of timestamptz DEFAULT now()) RETURNS TABLE(person_id text,name text,account_type text,agency_ids uuid[],agency_names text[],onboarded_at timestamptz,sign_ins bigint,active_days bigint,average_per_week numeric,first_sign_in timestamptz,last_sign_in timestamptz,days_since_last integer,dormant boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN
IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
RETURN QUERY SELECT r->>'person_id',regexp_replace(r->>'name','[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}','[email omitted]','g'),r->>'account_type',ARRAY(SELECT jsonb_array_elements_text(r->'agency_ids')::uuid),ARRAY(SELECT jsonb_array_elements_text(r->'agency_names')),(r->>'registered_at')::timestamptz,(r->>'sign_ins')::bigint,(r->>'active_days')::bigint,(r->>'average_per_week')::numeric,(r->>'first_sign_in')::timestamptz,(r->>'last_sign_in')::timestamptz,(r->>'days_since_last')::integer,(r->>'dormant')::boolean FROM public.reports_people_rows(_from,_to,jsonb_build_object('accounts',_accounts,'account_type','all','talent','all','source','all','status','any','agencies','[]'::jsonb,'stage','all','activity','all'),_as_of) r WHERE (r->>'registered')::boolean OR r->>'account_type'='trusted_contact'; END $$;
REVOKE ALL ON FUNCTION public.admin_sign_in_people(date,date,text,timestamptz) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.admin_sign_in_page(date,date,text,text,text,uuid,text,text,integer,integer,timestamptz)'::regprocedure); d:=replace(d,'BEGIN','BEGIN IF NOT public.reports_can(''download_raw_data'') THEN RAISE EXCEPTION ''REPORT_ACCESS_DENIED: Your Reports role does not allow raw downloads.'' USING ERRCODE=''42501''; END IF;'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.admin_sign_in_summary(_from date,_to date,_accounts text DEFAULT 'real',_as_of timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT public.reports_sign_in_summary(_from,_to,jsonb_build_object('accounts',_accounts,'account_type','all','talent','all','source','all','status','any','agencies','[]'::jsonb,'stage','all','activity','all'),_from-(_to-_from+1),_from-1,_as_of) $$;
CREATE OR REPLACE FUNCTION public.reports_person_timeline(_person_id text,_from date,_to date,_filters jsonb,_offset integer DEFAULT 0,_as_of timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE person jsonb; result jsonb; BEGIN
IF NOT public.reports_can('view_reports') THEN RAISE EXCEPTION 'REPORT_ACCESS_DENIED: Your Reports role does not allow this action.' USING ERRCODE='42501'; END IF;
SELECT r INTO person FROM public.reports_people_rows(_from,_to,_filters,_as_of) r WHERE r->>'person_id'=_person_id LIMIT 1; IF person IS NULL THEN RAISE EXCEPTION 'REPORT_PERSON_MISSING: This person no longer matches these filters.'; END IF;
WITH events AS (
SELECT i.id::text id,'invitation'::text kind,i.first_sent_at occurred_at,'Invitation sent'::text label FROM public.agency_invitations i WHERE lower(btrim(i.email))=person->>'email' AND i.first_sent_at IS NOT NULL
UNION ALL SELECT i.id::text,'invitation',i.first_sent_at,'Invitation sent' FROM public.independent_talent_invitations i WHERE lower(btrim(i.email))=person->>'email' AND i.first_sent_at IS NOT NULL
UNION ALL SELECT i.id::text,'invitation',i.first_sent_at,'Invitation sent' FROM public.talent_invitations i WHERE lower(btrim(i.email))=person->>'email' AND i.first_sent_at IS NOT NULL
UNION ALL SELECT 'registration','registration',(person->>'registered_at')::timestamptz,'Registered' WHERE (person->>'registered')::boolean AND person->>'registered_at' IS NOT NULL
UNION ALL SELECT 'onboarding','onboarding',(person->>'onboarded_at')::timestamptz,'Own validated upload · Onboarded' WHERE person->>'onboarded_at' IS NOT NULL
UNION ALL SELECT e.id::text,CASE WHEN e.action='login' THEN 'sign_in' WHEN e.action='vault_document_uploaded' THEN 'upload' WHEN e.action='vault_document_shared' THEN 'share' ELSE 'vault_action' END,e.created_at,CASE WHEN e.action='login' THEN 'Signed in' WHEN e.action='vault_document_uploaded' THEN 'Document uploaded' WHEN e.action='vault_document_shared' THEN 'Document shared' ELSE 'Vault activity' END FROM public.talent_audit_log e WHERE e.actor_id::text=_person_id AND (e.action='login' OR e.action LIKE 'vault_%')
UNION ALL SELECT e.id::text,e.event,e.created_at,CASE e.event WHEN 'successful_code' THEN 'Successful access-code visit' WHEN 'download' THEN 'Document downloaded' ELSE 'Document opened' END FROM public.loved_one_share_access_events e JOIN public.loved_one_shares s ON s.id=e.share_id JOIN public.talent_profiles t ON t.id=s.talent_id WHERE _person_id='recipient:'||md5(lower(btrim(s.loved_one_email))) AND t.deleted_at IS NULL AND (_filters->>'accounts'='all' OR t.is_test=(_filters->>'accounts'='test')) AND (_filters->>'status'='any' OR CASE WHEN t.paused_at IS NOT NULL THEN 'paused' WHEN t.suspended_at IS NOT NULL THEN 'suspended' ELSE 'active' END=_filters->>'status') AND (jsonb_array_length(COALESCE(_filters->'agencies','[]'))=0 OR EXISTS(SELECT 1 FROM public.agency_talent_links l,jsonb_array_elements_text(_filters->'agencies') a WHERE l.talent_user_id=t.user_id AND l.status='active' AND l.ended_at IS NULL AND l.agency_id=a.value::uuid)) AND (_filters->>'talent'='all' OR (_filters->>'talent'='agency_linked')=EXISTS(SELECT 1 FROM public.agency_talent_links l WHERE l.talent_user_id=t.user_id AND l.status='active' AND l.ended_at IS NULL)) AND (_filters->>'source'='all' OR EXISTS(SELECT 1 FROM public.independent_talent_invitations i WHERE i.accepted_at IS NOT NULL AND lower(btrim(i.email))=lower(btrim(t.email)) AND i.source=_filters->>'source') OR (_filters->>'source'='agency' AND EXISTS(SELECT 1 FROM public.talent_invitations i WHERE i.accepted_at IS NOT NULL AND lower(btrim(i.email))=lower(btrim(t.email)))))
), valid AS(SELECT * FROM events WHERE occurred_at IS NOT NULL AND occurred_at<LEAST((_to+1)::timestamp AT TIME ZONE 'Africa/Johannesburg',_as_of,now())), page AS(SELECT * FROM valid ORDER BY occurred_at DESC,id LIMIT 50 OFFSET GREATEST(0,_offset)) SELECT jsonb_build_object('total',(SELECT count(*) FROM valid),'rows',COALESCE((SELECT jsonb_agg(to_jsonb(p)) FROM page p),'[]'::jsonb),'messages_tracked',false) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reports_person_timeline(text,date,date,jsonb,integer,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reports_person_timeline(text,date,date,jsonb,integer,timestamptz) TO authenticated;
-- Rollback: restore previous sign-in SQL definitions; revoke Reports timeline access. Preserve audit, milestones and two-step settings.

 END IF;
END $reports_history$;
